import React, { useEffect, useState, useCallback } from "react";
import axios from "axios";
import {
  FaBookMedical,
  FaClipboardList,
  FaPlusCircle,
  FaTrash,
  FaEdit,
  FaLayerGroup
} from "react-icons/fa";
import AlertBox from "./AlertBox";

function TeacherDashboard() {
  const teacherId = localStorage.getItem("user_id");

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    subject_code: ""
  });

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);
  const [editCourseId, setEditCourseId] = useState(null);

  const fetchCourses = useCallback(async () => {
    try {
      const response = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = response.data.courses || [];
      const myCourses = allCourses.filter(
        (course) => String(course.teacher_id) === String(teacherId)
      );
      setCourses(myCourses);
    } catch (error) {
      console.error(error);
    }
  }, [teacherId]);

  useEffect(() => {
    fetchCourses();
  }, [fetchCourses]);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleEdit = (course) => {
    setFormData({
      title: course.title,
      description: course.description,
      subject_code: course.subject_code
    });
    setEditCourseId(course.id);
  };

  const handleDelete = async (courseId) => {
    try {
      const response = await axios.delete(
        `http://127.0.0.1:8000/delete-course/${courseId}`
      );
      setAlert({ message: response.data.message, type: "success" });
      fetchCourses();
    } catch (error) {
      setAlert({ message: "Course deletion failed", type: "error" });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const payload = {
        ...formData,
        teacher_id: parseInt(teacherId)
      };

      let response;

      if (editCourseId) {
        response = await axios.put(
          `http://127.0.0.1:8000/update-course/${editCourseId}`,
          payload
        );
      } else {
        response = await axios.post(
          "http://127.0.0.1:8000/create-course",
          payload
        );
      }

      setAlert({ message: response.data.message, type: "success" });
      setFormData({ title: "", description: "", subject_code: "" });
      setEditCourseId(null);
      fetchCourses();
    } catch (error) {
      setAlert({
        message: editCourseId ? "Course update failed" : "Course creation failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: "20px",
          marginBottom: "25px"
        }}
      >
        <div style={cardStyle("#ede7f6")}>
          <h3>Total Courses</h3>
          <p style={numberStyle}>{courses.length}</p>
        </div>
        <div style={cardStyle("#e3f2fd")}>
          <h3>Active Subjects</h3>
          <p style={numberStyle}>{courses.length}</p>
        </div>
        <div style={cardStyle("#f3e5f5")}>
          <h3>Teacher Panel</h3>
          <p style={numberStyle}><FaLayerGroup /></p>
        </div>
      </div>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1.2fr",
          gap: "25px"
        }}
      >
        <div style={panelStyle}>
          <h3 style={headingStyle}>
            <FaBookMedical /> {editCourseId ? "Edit Course" : "Add New Course"}
          </h3>

          <form onSubmit={handleSubmit} style={formStyle}>
            <input
              type="text"
              name="title"
              placeholder="Course Title"
              value={formData.title}
              onChange={handleChange}
              style={inputStyle}
            />
            <input
              type="text"
              name="description"
              placeholder="Course Description"
              value={formData.description}
              onChange={handleChange}
              style={inputStyle}
            />
            <input
              type="text"
              name="subject_code"
              placeholder="Subject Code"
              value={formData.subject_code}
              onChange={handleChange}
              style={inputStyle}
            />
            <button type="submit" style={primaryBtn}>
              <FaPlusCircle />
              {editCourseId ? "Update Course" : "Add Course"}
            </button>
          </form>
        </div>

        <div style={panelStyle}>
          <h3 style={headingStyle}>
            <FaClipboardList /> My Added Courses
          </h3>

          {courses.length === 0 ? (
            <p>No courses added yet.</p>
          ) : (
            courses.map((course) => (
              <div key={course.id} style={courseCard}>
                <h4>{course.title}</h4>
                <p>{course.description}</p>
                <p><strong>Subject Code:</strong> {course.subject_code}</p>

                <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
                  <button onClick={() => handleEdit(course)} style={editBtn}>
                    <FaEdit /> Edit
                  </button>
                  <button onClick={() => handleDelete(course.id)} style={deleteBtn}>
                    <FaTrash /> Delete
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

const cardStyle = (bg) => ({
  background: bg,
  borderRadius: "16px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.06)"
});

const numberStyle = {
  fontSize: "28px",
  fontWeight: "bold",
  color: "#4a148c"
};

const panelStyle = {
  background: "#fff",
  borderRadius: "18px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const headingStyle = {
  display: "flex",
  alignItems: "center",
  gap: "10px",
  color: "#6a1b9a",
  marginBottom: "18px"
};

const formStyle = {
  display: "flex",
  flexDirection: "column",
  gap: "14px"
};

const inputStyle = {
  padding: "12px",
  borderRadius: "10px",
  border: "1px solid #ccc",
  outline: "none"
};

const primaryBtn = {
  background: "#7b1fa2",
  color: "white",
  border: "none",
  padding: "12px",
  borderRadius: "10px",
  fontWeight: "bold",
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  gap: "8px"
};

const courseCard = {
  border: "1px solid #eee",
  borderRadius: "12px",
  padding: "14px",
  marginBottom: "12px",
  background: "#fafafa"
};

const editBtn = {
  background: "#1976d2",
  color: "white",
  border: "none",
  padding: "10px 14px",
  borderRadius: "8px",
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  gap: "8px"
};

const deleteBtn = {
  background: "#d32f2f",
  color: "white",
  border: "none",
  padding: "10px 14px",
  borderRadius: "8px",
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  gap: "8px"
};

export default TeacherDashboard;
